/*
* Private reference-order helpers adapted from Reference-LAPACK at commit
* 2e5d9c1273435fbd953adb294ed603e4789afaba: IDAMAX, DGEMV and DGEMMTR.
* DGEMMTR was written on 19-July-2023 by Martin Koehler, MPI Magdeburg.
* The full upstream BSD license is retained in dlasyf_ndarray.c and NOTICE.
*/
#ifndef STDLIB_LAPACK_BASE_DLASYF_PANEL_H
#define STDLIB_LAPACK_BASE_DLASYF_PANEL_H

#include "stdlib/blas/base/dcopy.h"
#include "stdlib/blas/base/dscal.h"
#include "stdlib/blas/base/dswap.h"
#include <math.h>
#include <stdint.h>

typedef struct dlasyf_view {
	double *data;
	intmax_t stride1;
	intmax_t stride2;
	intmax_t offset;
} dlasyf_view;

// One-based logical cells make the pinned panel algorithm's coordinates explicit.
#define DLASYF_CELL( view, row, column ) ( (view)->data[ (view)->offset+((row)-1)*(view)->stride1+((column)-1)*(view)->stride2 ] )

/**
* Computes a checked view's physical element index for an active logical cell.
*/
static intmax_t dlasyf_cell_index( const dlasyf_view *view, const intmax_t row, const intmax_t column ) {
	return view->offset+(row-1)*view->stride1+(column-1)*view->stride2;
}

/**
* Copies a logical vector through guarded existing DCOPY ndarray calls.
*
* Chunks contain at most seven elements so that each unit-stride portable
* call performs at most one unrolled group. Zero counts return before index
* arithmetic or derived pointer formation. Singleton strides are normalized.
*/
static void dlasyf_copy( const intmax_t count, const dlasyf_view *x, const intmax_t xr, const intmax_t xc, const int xaxis, dlasyf_view *y, const intmax_t yr, const intmax_t yc, const int yaxis ) {
	intmax_t strideX;
	intmax_t strideY;
	intmax_t offsetX;
	intmax_t offsetY;
	intmax_t length;
	intmax_t done;

	if ( count <= 0 ) return;
	strideX = xaxis == 0 ? x->stride1 : x->stride2;
	strideY = yaxis == 0 ? y->stride1 : y->stride2;
	offsetX = dlasyf_cell_index( x, xr, xc );
	offsetY = dlasyf_cell_index( y, yr, yc );
	done = 0;
	while ( done < count ) {
		length = count-done < 7 ? count-done : 7;
		API_SUFFIX(c_dcopy_ndarray)( (CBLAS_INT)length, x->data+offsetX+done*strideX, (CBLAS_INT)(length == 1 ? 1 : strideX), 0, y->data+offsetY+done*strideY, (CBLAS_INT)(length == 1 ? 1 : strideY), 0 );
		done += length;
	}
}

/**
* Scales a logical vector through the existing guarded DSCAL ndarray adapter.
*/
static void dlasyf_scale( const intmax_t count, const double alpha, dlasyf_view *x, const intmax_t row, const intmax_t column ) {
	intmax_t offset;

	if ( count <= 0 ) return;
	offset = dlasyf_cell_index( x, row, column );
	API_SUFFIX(c_dscal_ndarray)( (CBLAS_INT)count, alpha, x->data+offset, (CBLAS_INT)(count == 1 ? 1 : x->stride1), 0 );
}

/**
* Swaps row fragments through the existing guarded DSWAP ndarray adapter.
*/
static void dlasyf_swap( const intmax_t count, dlasyf_view *x, const intmax_t row1, const intmax_t row2, const intmax_t column ) {
	intmax_t offset1;
	intmax_t offset2;

	if ( count <= 0 || row1 == row2 ) return;
	offset1 = dlasyf_cell_index( x, row1, column );
	offset2 = dlasyf_cell_index( x, row2, column );
	API_SUFFIX(c_dswap_ndarray)( (CBLAS_INT)count, x->data+offset1, (CBLAS_INT)(count == 1 ? 1 : x->stride2), 0, x->data+offset2, (CBLAS_INT)(count == 1 ? 1 : x->stride2), 0 );
}

/**
* Returns the first absolute maximum's logical ordinal without allocation.
*/
static intmax_t dlasyf_first_max( const intmax_t count, const dlasyf_view *x, const intmax_t row, const intmax_t column ) {
	intmax_t winner;
	intmax_t i;
	double maximum;
	double value;

	if ( count < 1 ) return -1;
	if ( count == 1 ) return 0;
	maximum = fabs( DLASYF_CELL( x, row, column ) );
	winner = 0;
	for ( i = 1; i < count; i++ ) {
		value = fabs( DLASYF_CELL( x, row+i, column ) );
		if ( value > maximum ) {
			maximum = value;
			winner = i;
		}
	}
	return winner;
}

/**
* Performs only the reference NT GEMV mode, alpha=-1 and beta=1.
*
* Each multiplication is rounded before addition, including zero coefficients.
* Logical column then row order is independent of the views' physical strides.
*/
static void dlasyf_gemv( const intmax_t rows, const intmax_t columns, const dlasyf_view *a, const intmax_t ar, const intmax_t ac, dlasyf_view *w, const intmax_t xr, const intmax_t xc, const intmax_t yr, const intmax_t yc ) {
	intmax_t i;
	intmax_t j;
	double temp;
	volatile double product;

	if ( rows <= 0 || columns <= 0 ) return;
	for ( j = 0; j < columns; j++ ) {
		temp = -DLASYF_CELL( w, xr, xc+j );
		for ( i = 0; i < rows; i++ ) {
			product = temp*DLASYF_CELL( a, ar+i, ac+j );
			DLASYF_CELL( w, yr+i, yc ) += product;
		}
	}
}

/**
* Performs the required reference NT/T triangular update, alpha=-1, beta=1.
*
* Panel and destination cells within the same injective A view are disjoint.
* Zero block/factor sizes return before forming any panel-derived address.
*/
static void dlasyf_triangular( const LAPACK_UPLO uplo, const intmax_t order, const intmax_t factors, dlasyf_view *a, const intmax_t cr, const intmax_t cc, const intmax_t ar, const intmax_t ac, const dlasyf_view *w, const intmax_t wr, const intmax_t wc ) {
	intmax_t first;
	intmax_t last;
	intmax_t i;
	intmax_t j;
	intmax_t l;
	double temp;
	volatile double product;

	if ( order <= 0 || factors <= 0 ) return;
	for ( j = 0; j < order; j++ ) {
		first = uplo == LAPACK_UPPER_TRIANGLE ? 0 : j;
		last = uplo == LAPACK_UPPER_TRIANGLE ? j : order-1;
		for ( l = 0; l < factors; l++ ) {
			temp = -DLASYF_CELL( w, wr+j, wc+l );
			for ( i = first; i <= last; i++ ) {
				product = temp*DLASYF_CELL( a, ar+i, ac+l );
				DLASYF_CELL( a, cr+i, cc+j ) += product;
			}
		}
	}
}

#endif // !STDLIB_LAPACK_BASE_DLASYF_PANEL_H
